PT_STARTER_STORY={[21]={[0]={["ids"]={10269,10270},["text"]="Nghe nói quân Đông Bá Hầu Khương Văn Hoán đã chế tạo đại đao mới. Ngươi hãy tìm <color=red>Âu Thiên Hóa<color> hỏi xem có cách gì chế tạo vũ khí mới hay không?<enter>Vũ khí không sánh bằng quân địch, trong chiến tranh quân ta chẳng khác nào cá nằm trên thớt. Đây là chuyện liên quan đến tính mạng!"},[1]={["ids"]={10279},["text"]="Ta không biết phải dùng vật liệu gì để chế tạo thứ vũ khí mới đó. Đại công tử <color=red>Sùng ứng Bưu<color> hiểu nhiều biết rộng, hãy đến đó hỏi thử xem!"},[2]={["ids"]={10250},["text"]="Quân của Đông Bá Hầu chuyên dùng <color=red>Đoản Kiếm<color>. Ngươi hãy lên Yến Sơn đánh bọn <color=red>Kiếm Nhân<color> lấy về 10 thanh Đoản kiếm cho Âu Thiên Hóa xem thử"},[3]={["ids"]={10278},["text"]="Muốn thay đổi vật liệu đúc tạo đao kiếm, phải được <color=red>Bắc Bá Hầu Sùng Hầu Hổ<color> phê chuẩn mới được. Hãy để những vật liệu này ở chỗ ta, ngươi hãy đi tìm Hầu Gia trước!"},[4]={["ids"]={10247},["text"]="Phương pháp đúc rèn do tổ tiên truyền lại sao có thể thay đổi chứ! Nói Lỗ Hùng dừng làm những chuyện điên rồ nữa!"},[5]={["ids"]={10268},["text"]="Bắc Bá Hầu không cho phép, biết làm sao đây? Đúng rồi! Ngươi hãy đến tìm <color=red>Sùng Hắc Hổ<color>, ông ấy nhất định sẽ thuyết phục Bắc Bá Hầu."},[6]={["ids"]={10240},["text"]="Ta sẽ đi tìm huynh trưởng, ngươi không cần đợi ta, hãy đi bảo Âu Thiên Hóa thay đổi vật liệu."},[7]={["ids"]={10277},["text"]="Vừa mới nhận được thông báo của Bắc Bá Hầu. Ta sẽ thử nghiệm những vật liệu mới"},[8]={["ids"]={10267},["text"]="Hay lắm! Thật vất vả cho ngươi! Xin nhận chút phần thưởng!"}},[11]={[0]={["ids"]={10536,10537},["text"]="Ta đang chế luyện bộ pháp bảo Ngũ Thất Phiến, cần có <color=red>10 Băng Cơ<color> và <color=green>lửa<color>. <color=red>Hoàng Long Chân Nhân<color> có rất nhiều Băng Cơ. <color=red>Nhiên Đăng Đạo Nhân<color> có lửa, ngươi có thể giúp ta không?<enter>Vậy chuyện này trông cậy vào ngươi, nhớ <color=red>Hoàng Long Chân Nhân<color> có băng Cơ, <color=red>Nhiên Đăng Đạo Nhân<color> có lửa."},[1]={["ids"]={10557},["text"]="Thật không may! Băng Cơ vừa dùng hết! Nhưng ở chân núi Côn Lôn có rất nhiều <color=red>Tuyết Quái<color> giữ Băng Cơ. Hãy tìm 10 miếng giao cho Nam Cực Tiên ông."},[2]={["ids"]={10535},["text"]="Làm phiền ngươi quá! Nhưng để chế luyện cần phải có một loại lửa đặc biệt. Ngươi hãy đến <color=red>Nhiên Đăng Đạo Nhân<color> mượn lửa giúp ta!"},[3]={["ids"]={10527},["text"]="Mau đem Hỏa Thạch giao cho <color=red>Nam Cực Tiên Ông<color>."},[4]={["ids"]={10534},["text"]="Tốt lắm! Nhất định sẽ luyện được thành công Ngũ Thất Phiến. Đây là phần thưởng cho ngươi!"}},[31]={[0]={["ids"]={10156,10157},["text"]="Ta cần những trang bị có thể tăng năng lực cho Dị Nhân. Ngươi có thể giúp ta tìm không?<enter><color=red>Cao Giác<color> biết dị nhân cần loại trang bị nào."},[1]={["ids"]={10143},["text"]="Muốn tăng thêm năng lực cho trang bị? Ta nhất thời không nghĩ ra cách. Ngươi đến tìm huynh trưởng <color=red>Cao Minh<color> của ta đi! Huynh ấy có thể giúp!"},[2]={["ids"]={10149},["text"]="Nguyên liệu để tăng năng lực trang bị? Ta sẽ giúp ngươi! Nhưng trước tiên hãy giúp ta báo tin này cho <color=red>Hình Thiên<color> đã!"},[3]={["ids"]={10179},["text"]="Cao Minh quả thật không hỗ danh là Thiên Lý Nhãn. Tin tức này rất chính xác, ngươi có thể trở về phục mệnh với hắn!"},[4]={["ids"]={10148},["text"]="Ta đã tìm hiểu giúp ngươi rồi, nguyên liệu cần là <color=red>Mặt Quỷ<color>, trên <color=red>Xi Vưu Mộ<color> có rất nhiều Hỏa Diện, chúng sẽ rơi Mặt Quỷ. Chỉ cần lấy 10 cái là đủ!"},[5]={["ids"]={10155},["text"]="Ngươi đã tìm được Mặt quỷ ta cần, ta sẽ dùng chúng để tăng năng lực trang bị!"}}}
PT_STARTER_FINAL={[21]=9,[11]=5,[31]=6}
-- Original dialogue text and source IDs are emitted by build_starter_story.py.
-- Rewards below are the user's Loose policy, not original VNG reward values.
function PTStarterStep(a)
    return a and PT_STARTER_STORY[a.task] and PT_STARTER_STORY[a.task][a.from]
end
function PTStarterReward(a)
    return a.to==PT_STARTER_FINAL[a.task] and 5000 or 500
end
function PTStarterText(a,completed)
    local d=PTStarterStep(a)
    local text="<color=yellow>"..a.title.."<color><enter>"..d.text
    text=text.."<enter><enter><color=cyan>Mục tiêu hiện tại: "..a.note.."<color>"
    local verb=completed and "Đã nhận" or "Thưởng khi hoàn tất bước này"
    text=text.."<enter><color=green>"..verb..": "..PTStarterReward(a).." EXP"
    if a.money>0 then text=text.." + "..a.money.." lượng" end
    return text.."<color>"
end
-- Patch only the three reviewed level-three chains. Preserve all other steps.
function PTStarterInstall(prefix)
    local steps=prefix=="ptg" and PTG_STEPS or PT2_STEPS
    if not steps then return end
    for i=1,getn(steps) do
        if PTStarterStep(steps[i]) then steps[i].xp=PTStarterReward(steps[i]) end
    end
end
PTStarterInstall("ptg")
PTStarterInstall("pt2")
if PTGPreview and PTGApply and not PT_STARTER_G_INSTALLED then
    PT_STARTER_G_INSTALLED=1
    PT_STARTER_OLD_G_PREVIEW=PTGPreview
    PT_STARTER_OLD_G_APPLY=PTGApply
    function PTGPreview(i)
        local a=PTG_STEPS[i]
        if not PTStarterStep(a) then return PT_STARTER_OLD_G_PREVIEW(i) end
        if not PTGReady(a) then return end
        SayButtons(PTStarterText(a,nil),2,"Tiếp tục/ptg_yes"..i,"Quay lại/main")
    end
    function PTGApply(i)
        local a=PTG_STEPS[i]
        local before=a and GetTask(a.task)
        PT_STARTER_OLD_G_APPLY(i)
        if PTStarterStep(a) and before==a.from and GetTask(a.task)==a.to then
            Msg2Player("Nhận được "..a.xp.." điểm kinh nghiệm"..(a.money>0 and " và "..a.money.." lượng." or "."))
            PTGNotice(PTStarterText(a,1))
        end
    end
end
if PT2Preview and PT2Apply and not PT_STARTER_2_INSTALLED then
    PT_STARTER_2_INSTALLED=1
    PT_STARTER_OLD_2_PREVIEW=PT2Preview
    PT_STARTER_OLD_2_APPLY=PT2Apply
    function PT2Preview(i)
        local a=PT2_STEPS[i]
        if not PTStarterStep(a) then return PT_STARTER_OLD_2_PREVIEW(i) end
        if not PT2Ready(a) then return end
        SayButtons(PTStarterText(a,nil),2,"Tiếp tục/pt2_yes"..i,"Quay lại/main")
    end
    function PT2Apply(i)
        local a=PT2_STEPS[i]
        local before=a and GetTask(a.task)
        PT_STARTER_OLD_2_APPLY(i)
        if PTStarterStep(a) and before==a.from and GetTask(a.task)==a.to then
            Msg2Player("Nhận được "..a.xp.." điểm kinh nghiệm"..(a.money>0 and " và "..a.money.." lượng." or "."))
            PT2Notice(PTStarterText(a,1))
        end
    end
end
